"""
ComfyUI_VideoPrep Nodes
=====================
VideoPrep Time-to-Move animation tool for video generation.

Nodes:
- VideoPrep TTM Interactive Editor: Click-to-segment with SAM2, keyframe animation
- VideoPrep TTM Compose & Animate: Multi-layer compositor with background animation
"""

import os
import sys
import torch
import numpy as np
from PIL import Image
import cv2
import json
import folder_paths
import comfy.model_management

# ============================================================
# SAM2 Integration (optional - uses comfyui-sam2 if installed)
# ============================================================

SAM2_AVAILABLE = False
SAM2_MODEL_CACHE = {}
SAM2_MODEL_DIR = os.path.join(folder_paths.models_dir, "sam2")

sam2_node_path = os.path.join(os.path.dirname(os.path.dirname(__file__)), "comfyui-sam2")
if os.path.exists(sam2_node_path) and sam2_node_path not in sys.path:
    sys.path.insert(0, sam2_node_path)

try:
    from sam2.sam2_image_predictor import SAM2ImagePredictor
    SAM2_AVAILABLE = True
    print("[VideoPrep-TTM] ✓ SAM2 available for click-to-segment")
except Exception:
    print("[VideoPrep-TTM] ⚠ SAM2 not available - install 'comfyui-sam2' from ComfyUI Manager")


# ============================================================
# Utility Functions
# ============================================================

def load_sam2_for_points(model_name="sam2_hiera_tiny"):
    """Load SAM2 model using comfyui-sam2's loader."""
    global SAM2_MODEL_CACHE

    if not SAM2_AVAILABLE:
        return None
    if model_name in SAM2_MODEL_CACHE:
        return SAM2_MODEL_CACHE[model_name]

    try:
        original_cwd = os.getcwd()
        os.chdir(sam2_node_path)
        try:
            from node import load_sam_model, list_sam_model
            available = list_sam_model()
            target = None
            for m in available:
                for keyword in ["tiny", "small", "base", "large"]:
                    if keyword in model_name.lower() and keyword in m.lower():
                        target = m
                        break
                if target:
                    break
            if not target and available:
                target = available[0]
            if target:
                print(f"[VideoPrep-TTM] Loading SAM2 model: {target}")
                sam = load_sam_model(target)
                SAM2_MODEL_CACHE[model_name] = sam
                return sam
        finally:
            os.chdir(original_cwd)
    except Exception as e:
        print(f"[VideoPrep-TTM] SAM2 load error: {e}")
    return None


def segment_with_points(image_np, points, sam_model):
    """Segment image using SAM2 with point prompts.
    points: list of [x, y, label] where label=1 is include, label=0 is exclude.
    """
    if sam_model is None or len(points) == 0:
        return None
    try:
        predictor = SAM2ImagePredictor(sam_model)
        image_rgb = image_np[:, :, :3] if image_np.shape[-1] == 4 else image_np
        predictor.set_image(image_rgb)

        point_coords = np.array([[p[0], p[1]] for p in points], dtype=np.float32)
        point_labels = np.array([p[2] if len(p) > 2 else 1 for p in points], dtype=np.int32)

        masks, scores, _ = predictor.predict(
            point_coords=point_coords, point_labels=point_labels, multimask_output=True
        )
        best_idx = np.argmax(scores)
        return masks[best_idx]
    except Exception as e:
        print(f"[VideoPrep-TTM] Segmentation error: {e}")
        return None


def mask_to_polygon(mask, simplify=True):
    """Convert binary mask to polygon points."""
    mask_uint8 = (mask * 255).astype(np.uint8)
    contours, _ = cv2.findContours(mask_uint8, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if not contours:
        return None
    largest = max(contours, key=cv2.contourArea)
    if simplify:
        largest = cv2.approxPolyDP(largest, 0.002 * cv2.arcLength(largest, True), True)
    polygon = largest.squeeze().tolist()
    return [polygon] if isinstance(polygon[0], (int, float)) else polygon


def tensor_to_numpy(tensor):
    """Convert ComfyUI tensor (B,H,W,C) to numpy BGR."""
    if tensor is None:
        return None
    img = (tensor[0].cpu().numpy() * 255).clip(0, 255).astype(np.uint8)
    return cv2.cvtColor(img, cv2.COLOR_RGB2BGR) if img.shape[-1] == 3 else img


def numpy_to_tensor(img):
    """Convert numpy BGR to ComfyUI tensor (1,H,W,C)."""
    if img is None:
        return None
    if len(img.shape) == 2:
        img = cv2.cvtColor(img, cv2.COLOR_GRAY2RGB)
    elif img.shape[-1] == 3:
        img = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)
    elif img.shape[-1] == 4:
        img = cv2.cvtColor(img, cv2.COLOR_BGRA2RGB)
    return torch.from_numpy(img.astype(np.float32) / 255.0).unsqueeze(0)


def mask_to_tensor(mask):
    """Convert numpy mask to ComfyUI mask tensor."""
    if mask is None:
        return None
    if len(mask.shape) == 3:
        mask = mask[:, :, 0]
    return torch.from_numpy(mask.astype(np.float32) / 255.0).unsqueeze(0)


def inpaint_background(image_bgr, mask_bool):
    """Inpaint masked regions of the background."""
    return cv2.inpaint(image_bgr, (mask_bool.astype(np.uint8) * 255), 3, cv2.INPAINT_TELEA)


def apply_hue_shift(img_bgr, hue_deg):
    """Rotate hue by degrees."""
    if abs(hue_deg) < 1e-6:
        return img_bgr.copy()
    hsv = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2HSV)
    h = hsv[:, :, 0].astype(np.int16)
    h = (h + int(round((hue_deg / 360.0) * 179.0))) % 180
    hsv[:, :, 0] = h.astype(np.uint8)
    return cv2.cvtColor(hsv, cv2.COLOR_HSV2BGR)


def smooth_path_bezier(points, num_samples):
    """Smooth a path using cubic spline interpolation."""
    if len(points) < 2:
        return np.array(points)
    points = np.array(points, dtype=np.float32)
    t = np.linspace(0, 1, len(points))
    t_smooth = np.linspace(0, 1, num_samples)
    try:
        from scipy import interpolate
        cs_x = interpolate.CubicSpline(t, points[:, 0])
        cs_y = interpolate.CubicSpline(t, points[:, 1])
        return np.column_stack([cs_x(t_smooth), cs_y(t_smooth)]).astype(np.float32)
    except (ImportError, Exception):
        pass
    return np.column_stack([
        np.interp(t_smooth, t, points[:, 0]),
        np.interp(t_smooth, t, points[:, 1])
    ]).astype(np.float32)


def animate_cutout(image_bgr, polygon_xy, path_xy, scales, rotations, origin_xy=None):
    """Animate a polygon cutout along a path with scale and rotation. Returns RGBA frames."""
    h, w = image_bgr.shape[:2]
    frames = []
    origin = np.array(origin_xy if origin_xy is not None else polygon_xy.mean(axis=0), dtype=np.float32)

    for i in range(len(path_xy)):
        theta = np.deg2rad(rotations[i])
        s = float(scales[i])
        cos_t, sin_t = np.cos(theta), np.sin(theta)

        M = np.array([
            [s * cos_t, -s * sin_t, path_xy[i, 0] - (s * cos_t * origin[0] - s * sin_t * origin[1])],
            [s * sin_t, s * cos_t, path_xy[i, 1] - (s * sin_t * origin[0] + s * cos_t * origin[1])]
        ], dtype=np.float32)

        warped = cv2.warpAffine(image_bgr, M, (w, h), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)

        poly = polygon_xy.astype(np.float32)
        pts = np.hstack([poly, np.ones((len(poly), 1), dtype=np.float32)])
        poly_t = (M @ pts.T).T.astype(np.int32)

        mask = np.zeros((h, w), dtype=np.uint8)
        cv2.fillPoly(mask, [poly_t], 255)

        rgba = np.zeros((h, w, 4), dtype=np.uint8)
        rgba[:, :, :3] = warped
        rgba[:, :, 3] = mask
        frames.append(rgba)
    return frames


def interpolate_bg_keyframe(bg_keyframes, t_eased):
    """Interpolate background keyframes at time t_eased (0-1).
    Used by both InteractiveEditor and ComposeAnimate (DRY).
    """
    bg_K = len(bg_keyframes)
    if bg_K == 1:
        return bg_keyframes[0]

    t_bg = t_eased * (bg_K - 1)
    bg_idx = int(t_bg)
    bg_frac = t_bg - bg_idx

    if bg_idx >= bg_K - 1:
        return bg_keyframes[-1]

    k1, k2 = bg_keyframes[bg_idx], bg_keyframes[bg_idx + 1]
    return {
        "x": k1.get("x", 0.5) + (k2.get("x", 0.5) - k1.get("x", 0.5)) * bg_frac,
        "y": k1.get("y", 0.5) + (k2.get("y", 0.5) - k1.get("y", 0.5)) * bg_frac,
        "scale": k1.get("scale", 1.0) + (k2.get("scale", 1.0) - k1.get("scale", 1.0)) * bg_frac,
        "rotation": k1.get("rotation", 0.0) + (k2.get("rotation", 0.0) - k1.get("rotation", 0.0)) * bg_frac,
    }


def apply_bg_transform(bg_np, bg_kf, W, H):
    """Apply pan/zoom/rotate transform to background frame.
    Used by both InteractiveEditor and ComposeAnimate (DRY).
    """
    bg_scale = bg_kf.get("scale", 1.0)
    bg_rot = bg_kf.get("rotation", 0.0)
    bg_pan_x = (bg_kf.get("x", 0.5) - 0.5) * W * 0.5
    bg_pan_y = (bg_kf.get("y", 0.5) - 0.5) * H * 0.5

    if bg_scale != 1.0 or bg_rot != 0.0 or bg_pan_x != 0 or bg_pan_y != 0:
        M_bg = cv2.getRotationMatrix2D((W / 2, H / 2), bg_rot, bg_scale)
        M_bg[0, 2] += bg_pan_x
        M_bg[1, 2] += bg_pan_y
        return cv2.warpAffine(bg_np, M_bg, (W, H), borderMode=cv2.BORDER_REFLECT)
    return bg_np.copy()


def apply_easing(t, motion_ease):
    """Apply easing function to time value t (0-1)."""
    if motion_ease == "ease_in":
        return t ** 2
    elif motion_ease == "ease_out":
        return 1 - (1 - t) ** 2
    elif motion_ease == "ease_in_out":
        return 0.5 * (1 - np.cos(t * np.pi))
    return t


# ============================================================
# VideoPrep TTM Interactive Editor
# ============================================================

class TTMInteractiveEditor:
    """
    Interactive editor for TTM animation.
    Click to segment with SAM2, drag to create keyframes.
    Supports background animation (pan/zoom/rotate).
    """

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "image": ("IMAGE",),
            },
            "optional": {
                "editor_data": ("STRING", {"default": "{}", "multiline": False}),
                "sam2_model": (["sam2_hiera_tiny", "sam2_hiera_small.pt",
                               "sam2_hiera_base_plus.pt", "sam2_hiera_large.pt"],),
            }
        }

    RETURN_TYPES = ("IMAGE", "MASK", "STRING")
    RETURN_NAMES = ("motion_video", "mask_video", "animation_data")
    FUNCTION = "process"
    CATEGORY = "VideoPrep/TTM"
    OUTPUT_NODE = True

    def process(self, image, editor_data="{}", sam2_model="sam2_hiera_tiny"):
        try:
            data = json.loads(editor_data)
        except Exception:
            data = {}

        if not data.get("layers"):
            h, w = image.shape[1], image.shape[2]
            return (image, torch.zeros((1, h, w), dtype=torch.float32), "{}")

        img_np = tensor_to_numpy(image)
        H, W = img_np.shape[:2]
        img_rgb = cv2.cvtColor(img_np, cv2.COLOR_BGR2RGB) if img_np.shape[-1] == 3 else img_np[:, :, :3]

        # Load SAM2 if needed
        sam_model = None
        if any(ld.get("segment_points") for ld in data.get("layers", [])) and SAM2_AVAILABLE:
            sam_model = load_sam2_for_points(sam2_model)

        # Process layers
        layers = []
        for layer_data in data.get("layers", []):
            polygon, mask = None, None

            segment_points = layer_data.get("segment_points", [])
            if segment_points and sam_model:
                sam_mask = segment_with_points(img_rgb, segment_points, sam_model)
                if sam_mask is not None:
                    polygon = mask_to_polygon(sam_mask)
                    if polygon:
                        polygon = np.array(polygon, dtype=np.float32)
                        mask = (sam_mask * 255).astype(np.uint8)

            if polygon is None:
                polygon = np.array(layer_data.get("polygon", []), dtype=np.float32)
            if len(polygon) < 3:
                continue
            if mask is None:
                mask = np.zeros((H, W), dtype=np.uint8)
                cv2.fillPoly(mask, [polygon.astype(np.int32)], 255)

            layers.append({
                "name": layer_data.get("name", "Layer"),
                "image": img_np, "mask": mask / 255.0,
                "polygon": polygon, "origin": polygon.mean(axis=0),
                "keyframes": layer_data.get("keyframes", [])
            })

        if not layers:
            h, w = image.shape[1], image.shape[2]
            return (image, torch.zeros((1, h, w), dtype=torch.float32), "{}")

        total_frames = data.get("total_frames", 81)

        # Inpaint background
        total_mask = np.zeros((H, W), dtype=bool)
        for layer in layers:
            total_mask |= (layer["mask"] > 0.5)
        bg_inpainted = inpaint_background(img_np, total_mask)

        # Background animation
        bg_keyframes = data.get("bgLayer", {}).get(
            "keyframes", [{"x": 0.5, "y": 0.5, "scale": 1.0, "rotation": 0.0}]
        )

        # Animate each layer
        all_layer_frames = []
        for layer in layers:
            keyframes = layer["keyframes"]
            if len(keyframes) < 2:
                kf = keyframes[0] if keyframes else {
                    "x": layer["origin"][0], "y": layer["origin"][1],
                    "rotation": 0, "scale": 1, "hue": 0
                }
                keyframes = [kf, kf.copy()]

            K = len(keyframes)
            positions = np.array([[kf["x"], kf["y"]] for kf in keyframes], dtype=np.float32)
            scales = np.array([kf.get("scale", 1.0) for kf in keyframes], dtype=np.float32)
            rotations = np.array([kf.get("rotation", 0.0) for kf in keyframes], dtype=np.float32)
            hues = np.array([kf.get("hue", 0.0) for kf in keyframes], dtype=np.float32)

            try:
                positions = smooth_path_bezier(positions, total_frames)
            except Exception:
                t_orig = np.linspace(0, 1, K)
                t_new = np.linspace(0, 1, total_frames)
                positions = np.column_stack([
                    np.interp(t_new, t_orig, positions[:, 0]),
                    np.interp(t_new, t_orig, positions[:, 1])
                ])

            t_orig = np.linspace(0, 1, K)
            t_new = np.linspace(0, 1, total_frames)
            scales_interp = np.interp(t_new, t_orig, scales)
            rotations_interp = np.interp(t_new, t_orig, rotations)
            hues_interp = np.interp(t_new, t_orig, hues)

            layer_frames = []
            for i in range(total_frames):
                img_shifted = apply_hue_shift(layer["image"], hues_interp[i])
                frames_single = animate_cutout(
                    img_shifted, layer["polygon"],
                    positions[i:i + 1], scales_interp[i:i + 1], rotations_interp[i:i + 1],
                    layer["origin"]
                )
                layer_frames.append(frames_single[0])
            all_layer_frames.append(layer_frames)

        # Composite with BG animation
        motion_frames = []
        for t in range(total_frames):
            t_norm = t / max(1, total_frames - 1)
            bg_kf = interpolate_bg_keyframe(bg_keyframes, t_norm)
            frame = apply_bg_transform(bg_inpainted, bg_kf, W, H)

            for layer_frames in all_layer_frames:
                lf = layer_frames[t]
                if lf.shape[-1] == 4:
                    alpha = lf[:, :, 3:4] / 255.0
                    frame = (frame * (1 - alpha) + lf[:, :, :3] * alpha).astype(np.uint8)
            motion_frames.append(frame)

        # Mask video
        mask_frames = []
        for t in range(total_frames):
            combined = np.zeros((H, W), dtype=np.uint8)
            for layer_frames in all_layer_frames:
                combined = np.maximum(combined, layer_frames[t][:, :, 3])
            mask_frames.append(combined)

        motion_video = torch.cat([numpy_to_tensor(f) for f in motion_frames], dim=0)
        mask_video = torch.cat([mask_to_tensor(m) for m in mask_frames], dim=0)

        return (motion_video, mask_video, json.dumps(data))


# ============================================================
# VideoPrep TTM Compose & Animate
# ============================================================

class TTMComposeAnimate:
    """
    Interactive multi-layer animation compositor.
    - Up to 4 subjects on a background
    - Interactive keyframe editing
    - Background pan/zoom/rotate animation
    - Timeline preview
    """

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "background": ("IMAGE",),
                "total_frames": ("INT", {"default": 81, "min": 2, "max": 500}),
            },
            "optional": {
                "subject1": ("IMAGE",), "mask1": ("MASK",),
                "subject2": ("IMAGE",), "mask2": ("MASK",),
                "subject3": ("IMAGE",), "mask3": ("MASK",),
                "subject4": ("IMAGE",), "mask4": ("MASK",),
                "editor_data": ("STRING", {"default": "{}", "multiline": False}),
                "motion_ease": (["linear", "ease_in", "ease_out", "ease_in_out"],),
            }
        }

    RETURN_TYPES = ("IMAGE", "MASK", "IMAGE")
    RETURN_NAMES = ("animation_frames", "mask_video", "preview_frame")
    FUNCTION = "compose_animate"
    CATEGORY = "VideoPrep/TTM"
    OUTPUT_NODE = True

    def compose_animate(self, background, total_frames,
                        subject1=None, mask1=None, subject2=None, mask2=None,
                        subject3=None, mask3=None, subject4=None, mask4=None,
                        editor_data="{}", motion_ease="ease_in_out"):
        try:
            data = json.loads(editor_data)
        except Exception:
            data = {}

        bg_np = tensor_to_numpy(background)
        H, W = bg_np.shape[:2]

        # Collect subjects
        subjects = []
        for i, (subj, mask) in enumerate([
            (subject1, mask1), (subject2, mask2),
            (subject3, mask3), (subject4, mask4)
        ]):
            if subj is None or mask is None:
                continue
            subj_np = tensor_to_numpy(subj)
            mask_np = mask[0].cpu().numpy()
            sh, sw = subj_np.shape[:2]
            if mask_np.shape != (sh, sw):
                mask_np = cv2.resize(mask_np, (sw, sh))

            layer_data = data.get("layers", {}).get(str(i), {})
            raw_kfs = layer_data.get("keyframes")

            if raw_kfs:
                keyframes = [{
                    "x": max(0, min(1, kf.get("x", 0.5))) * W,
                    "y": max(0, min(1, kf.get("y", 0.5))) * H,
                    "scale": kf.get("scale", 1.0),
                    "rotation": kf.get("rotation", 0.0)
                } for kf in raw_kfs]
            else:
                keyframes = [{"x": W * 0.5, "y": H * 0.5, "scale": 1.0, "rotation": 0.0}]

            subjects.append({
                "image": subj_np, "mask": mask_np,
                "keyframes": keyframes, "size": (sw, sh)
            })

        if not subjects:
            empty_mask = torch.zeros((1, H, W), dtype=torch.float32)
            return (background, empty_mask, background)

        # BG keyframes
        bg_keyframes = data.get("bgLayer", {}).get(
            "keyframes", [{"x": 0.5, "y": 0.5, "scale": 1.0, "rotation": 0.0}]
        )

        # Generate frames
        frames, mask_frames = [], []

        for frame_idx in range(total_frames):
            t = frame_idx / max(1, total_frames - 1)
            t_eased = apply_easing(t, motion_ease)

            # Background animation (DRY utility)
            bg_kf = interpolate_bg_keyframe(bg_keyframes, t_eased)
            frame = apply_bg_transform(bg_np, bg_kf, W, H)
            combined_mask = np.zeros((H, W), dtype=np.uint8)

            # Composite each subject
            for subj in subjects:
                kfs = subj["keyframes"]
                K = len(kfs)

                if K == 1:
                    kf = kfs[0]
                    tx, ty = kf["x"], kf["y"]
                    scale, rotation = kf.get("scale", 1.0), kf.get("rotation", 0.0)
                else:
                    t_kf = t_eased * (K - 1)
                    ki = min(int(t_kf), K - 2)
                    frac = t_kf - ki
                    k1, k2 = kfs[ki], kfs[ki + 1]
                    tx = k1["x"] + (k2["x"] - k1["x"]) * frac
                    ty = k1["y"] + (k2["y"] - k1["y"]) * frac
                    scale = k1.get("scale", 1.0) + (k2.get("scale", 1.0) - k1.get("scale", 1.0)) * frac
                    rotation = k1.get("rotation", 0.0) + (k2.get("rotation", 0.0) - k1.get("rotation", 0.0)) * frac

                subj_np = subj["image"]
                mask_np = subj["mask"]
                sh, sw = subj_np.shape[:2]
                if mask_np.max() > 1.0:
                    mask_np = mask_np / 255.0

                final_scale = 0.3 * scale  # Match JS preview scale

                M = cv2.getRotationMatrix2D((sw / 2, sh / 2), rotation, final_scale)
                M[0, 2] += tx - sw / 2
                M[1, 2] += ty - sh / 2

                warped_subj = cv2.warpAffine(subj_np, M, (W, H), borderMode=cv2.BORDER_CONSTANT)
                warped_mask = cv2.warpAffine(mask_np.astype(np.float32), M, (W, H), borderMode=cv2.BORDER_CONSTANT)

                alpha = warped_mask[:, :, np.newaxis]
                frame = (warped_subj * alpha + frame * (1 - alpha)).astype(np.uint8)
                combined_mask = np.maximum(combined_mask, (warped_mask * 255).clip(0, 255).astype(np.uint8))

            frames.append(frame)
            mask_frames.append(combined_mask)

        animation_frames = torch.cat([numpy_to_tensor(f) for f in frames], dim=0)
        mask_video = torch.cat([mask_to_tensor(m) for m in mask_frames], dim=0)
        preview_frame = numpy_to_tensor(frames[total_frames // 2])

        return (animation_frames, mask_video, preview_frame)


