NODE_CLASS_MAPPINGS = {
    "VideoPrepTTMInteractiveEditor": TTMInteractiveEditor,
    "VideoPrepTTMComposeAnimate": TTMComposeAnimate,
}

NODE_DISPLAY_NAME_MAPPINGS = {
    "VideoPrepTTMInteractiveEditor": "VideoPrep TTM Interactive Editor",
    "VideoPrepTTMComposeAnimate": "VideoPrep TTM Compose & Animate",
}

