import { app } from "../../scripts/app.js";
import { api } from "../../scripts/api.js";

// VideoPrep Interactive Crop Widget
// Allows dragging a rectangle on image to define crop region

app.registerExtension({
    name: "VideoPrep.InteractiveCrop",

    async beforeRegisterNodeDef(nodeType, nodeData, app) {
        if (nodeData.name === "VideoPrepInteractiveCrop") {

            const onNodeCreated = nodeType.prototype.onNodeCreated;
            nodeType.prototype.onNodeCreated = function() {
                const result = onNodeCreated?.apply(this, arguments);

                // Initialize crop state
                this.cropState = {
                    x: 0,
                    y: 0,
                    width: 512,
                    height: 512,
                    isDragging: false,
                    dragMode: null,
                    startX: 0,
                    startY: 0,
                    startCropX: 0,
                    startCropY: 0,
                    startCropW: 0,
                    startCropH: 0,
                    imageWidth: 0,
                    imageHeight: 0,
                    previewScale: 1,
                    previewOffsetX: 0,
                    previewOffsetY: 0,
                };

                // Image element for preview
                this.previewImage = null;
                this.previewImageSrc = null;

                // Find the crop_data widget
                const cropDataWidget = this.widgets?.find(w => w.name === "crop_data");
                if (cropDataWidget) {
                    try {
                        const data = JSON.parse(cropDataWidget.value);
                        this.cropState.x = data.x || 0;
                        this.cropState.y = data.y || 0;
                        this.cropState.width = data.width || 512;
                        this.cropState.height = data.height || 512;
                    } catch (e) {}
                }

                // Set minimum size for preview
                this.size[1] = Math.max(this.size[1], 400);

                return result;
            };

            // Handle workflow load - restore crop from saved widget
            const onConfigure = nodeType.prototype.onConfigure;
            nodeType.prototype.onConfigure = function(info) {
                if (onConfigure) onConfigure.apply(this, arguments);

                // Restore crop state from saved widget value
                setTimeout(() => {
                    const cropDataWidget = this.widgets?.find(w => w.name === "crop_data");
                    if (cropDataWidget && cropDataWidget.value) {
                        try {
                            const data = JSON.parse(cropDataWidget.value);
                            if (this.cropState) {
                                this.cropState.x = data.x || 0;
                                this.cropState.y = data.y || 0;
                                this.cropState.width = data.width || 512;
                                this.cropState.height = data.height || 512;
                                console.log("[VideoPrep-Crop] Restored crop region from saved workflow");
                                this.setDirtyCanvas(true);
                            }
                        } catch (e) {}
                    }
                }, 100);
            };

            // Fetch image from connected node
            nodeType.prototype.fetchPreviewImage = async function() {
                // Get the connected image node
                const imageInput = this.inputs?.find(i => i.name === "image");
                if (!imageInput || !imageInput.link) {
                    this.previewImage = null;
                    return;
                }

                const link = app.graph.links[imageInput.link];
                if (!link) return;

                const sourceNode = app.graph.getNodeById(link.origin_id);
                if (!sourceNode) return;

                // Try to get image from source node's imgs array (set after execution)
                if (sourceNode.imgs && sourceNode.imgs.length > 0) {
                    const imgSrc = sourceNode.imgs[0].src;
                    if (imgSrc !== this.previewImageSrc) {
                        this.previewImageSrc = imgSrc;
                        this.previewImage = new Image();
                        this.previewImage.onload = () => {
                            this.cropState.imageWidth = this.previewImage.naturalWidth;
                            this.cropState.imageHeight = this.previewImage.naturalHeight;
                            // Initialize crop to full image if not set
                            if (this.cropState.width > this.cropState.imageWidth) {
                                this.cropState.width = this.cropState.imageWidth;
                            }
                            if (this.cropState.height > this.cropState.imageHeight) {
                                this.cropState.height = this.cropState.imageHeight;
                            }
                            this.setDirtyCanvas(true);
                        };
                        this.previewImage.src = imgSrc;
                    }
                }

                // Also check if source has imageData property
                if (sourceNode.imageData) {
                    // Convert tensor data to image URL if available
                }
            };

            // Custom drawing for the node
            const onDrawForeground = nodeType.prototype.onDrawForeground;
            nodeType.prototype.onDrawForeground = function(ctx) {
                if (onDrawForeground) {
                    onDrawForeground.apply(this, arguments);
                }

                // Try to fetch preview image from connected node
                this.fetchPreviewImage();

                // Get preview area bounds
                const previewY = this.size[1] - 280;
                const previewHeight = 260;
                const previewWidth = this.size[0] - 20;
                const previewX = 10;

                // Draw background
                ctx.fillStyle = "#1a1a2e";
                ctx.fillRect(previewX, previewY, previewWidth, previewHeight);

                // Draw border
                ctx.strokeStyle = "#333";
                ctx.lineWidth = 1;
                ctx.strokeRect(previewX, previewY, previewWidth, previewHeight);

                // Draw instruction text
                ctx.fillStyle = "#888";
                ctx.font = "11px Arial";
                ctx.fillText("Drag to crop | Corners to resize | Double-click to reset", previewX + 5, previewY + 14);

                // Draw crop rectangle info
                const state = this.cropState;
                ctx.fillStyle = "#4ecdc4";
                ctx.font = "12px monospace";
                ctx.fillText(`X:${state.x} Y:${state.y} | ${state.width} × ${state.height}`, previewX + 5, previewY + 28);

                // Image preview area
                const imgAreaY = previewY + 35;
                const imgAreaHeight = previewHeight - 45;
                const imgAreaWidth = previewWidth - 10;
                const imgAreaX = previewX + 5;

                // Draw image if available
                if (this.previewImage && this.previewImage.complete && this.previewImage.naturalWidth > 0) {
                    state.imageWidth = this.previewImage.naturalWidth;
                    state.imageHeight = this.previewImage.naturalHeight;

                    // Calculate scale to fit
                    const scale = Math.min(
                        imgAreaWidth / state.imageWidth,
                        imgAreaHeight / state.imageHeight
                    );
                    state.previewScale = scale;

                    const scaledImgW = state.imageWidth * scale;
                    const scaledImgH = state.imageHeight * scale;
                    const imgX = imgAreaX + (imgAreaWidth - scaledImgW) / 2;
                    const imgY = imgAreaY + (imgAreaHeight - scaledImgH) / 2;

                    // Store for mouse handling
                    state.previewOffsetX = imgX;
                    state.previewOffsetY = imgY;

                    // Draw the actual image
                    ctx.drawImage(this.previewImage, imgX, imgY, scaledImgW, scaledImgH);

                    // Draw semi-transparent overlay outside crop region
                    ctx.fillStyle = "rgba(0, 0, 0, 0.6)";

                    const cropX = imgX + state.x * scale;
                    const cropY = imgY + state.y * scale;
                    const cropW = Math.min(state.width, state.imageWidth - state.x) * scale;
                    const cropH = Math.min(state.height, state.imageHeight - state.y) * scale;

                    // Top region
                    ctx.fillRect(imgX, imgY, scaledImgW, cropY - imgY);
                    // Bottom region
                    ctx.fillRect(imgX, cropY + cropH, scaledImgW, imgY + scaledImgH - (cropY + cropH));
                    // Left region
                    ctx.fillRect(imgX, cropY, cropX - imgX, cropH);
                    // Right region
                    ctx.fillRect(cropX + cropW, cropY, imgX + scaledImgW - (cropX + cropW), cropH);

                    // Draw crop border
                    ctx.strokeStyle = "#4ecdc4";
                    ctx.lineWidth = 2;
                    ctx.strokeRect(cropX, cropY, cropW, cropH);

                    // Draw corner handles
                    ctx.fillStyle = "#4ecdc4";
                    const handleSize = 10;

                    // TL corner
                    ctx.fillRect(cropX - handleSize/2, cropY - handleSize/2, handleSize, handleSize);
                    // TR corner
                    ctx.fillRect(cropX + cropW - handleSize/2, cropY - handleSize/2, handleSize, handleSize);
                    // BL corner
                    ctx.fillRect(cropX - handleSize/2, cropY + cropH - handleSize/2, handleSize, handleSize);
                    // BR corner
                    ctx.fillRect(cropX + cropW - handleSize/2, cropY + cropH - handleSize/2, handleSize, handleSize);

                    // Draw image boundary
                    ctx.strokeStyle = "#555";
                    ctx.lineWidth = 1;
                    ctx.strokeRect(imgX, imgY, scaledImgW, scaledImgH);

                } else {
                    // No image - show placeholder
                    ctx.fillStyle = "#2a2a3e";
                    ctx.fillRect(imgAreaX, imgAreaY, imgAreaWidth, imgAreaHeight);

                    ctx.fillStyle = "#666";
                    ctx.font = "14px Arial";
                    ctx.textAlign = "center";
                    ctx.fillText("Connect an image and run the workflow", 
                                imgAreaX + imgAreaWidth/2, imgAreaY + imgAreaHeight/2 - 10);
                    ctx.fillText("to see preview", 
                                imgAreaX + imgAreaWidth/2, imgAreaY + imgAreaHeight/2 + 10);
                    ctx.textAlign = "left";

                    // Set default dimensions for the rectangle preview
                    if (state.imageWidth === 0) {
                        state.imageWidth = 1024;
                        state.imageHeight = 1024;
                    }
                }
            };

            // Handle mouse events
            const onMouseDown = nodeType.prototype.onMouseDown;
            nodeType.prototype.onMouseDown = function(e, localPos, graphCanvas) {
                const previewY = this.size[1] - 280;

                // Check if click is in preview area
                if (localPos[1] > previewY + 35 && localPos[1] < this.size[1] - 10) {
                    const state = this.cropState;

                    if (state.imageWidth > 0 && state.previewScale > 0) {
                        const scale = state.previewScale;
                        const imgX = state.previewOffsetX;
                        const imgY = state.previewOffsetY;
                        const scaledImgW = state.imageWidth * scale;
                        const scaledImgH = state.imageHeight * scale;

                        const cropX = imgX + state.x * scale;
                        const cropY = imgY + state.y * scale;
                        const cropW = Math.min(state.width, state.imageWidth - state.x) * scale;
                        const cropH = Math.min(state.height, state.imageHeight - state.y) * scale;

                        const mx = localPos[0];
                        const my = localPos[1];
                        const handleSize = 15;

                        // Check corners first (larger hit area)
                        if (Math.abs(mx - cropX) < handleSize && Math.abs(my - cropY) < handleSize) {
                            state.dragMode = 'resize-tl';
                        } else if (Math.abs(mx - (cropX + cropW)) < handleSize && Math.abs(my - cropY) < handleSize) {
                            state.dragMode = 'resize-tr';
                        } else if (Math.abs(mx - cropX) < handleSize && Math.abs(my - (cropY + cropH)) < handleSize) {
                            state.dragMode = 'resize-bl';
                        } else if (Math.abs(mx - (cropX + cropW)) < handleSize && Math.abs(my - (cropY + cropH)) < handleSize) {
                            state.dragMode = 'resize-br';
                        }
                        // Check if inside crop region (move)
                        else if (mx > cropX && mx < cropX + cropW && my > cropY && my < cropY + cropH) {
                            state.dragMode = 'move';
                        }
                        // Check if in image area (new selection)
                        else if (mx > imgX && mx < imgX + scaledImgW && my > imgY && my < imgY + scaledImgH) {
                            state.dragMode = 'new';
                            state.x = Math.max(0, Math.round((mx - imgX) / scale));
                            state.y = Math.max(0, Math.round((my - imgY) / scale));
                            state.width = 8;
                            state.height = 8;
                        }

                        if (state.dragMode) {
                            state.isDragging = true;
                            state.startX = mx;
                            state.startY = my;
                            state.startCropX = state.x;
                            state.startCropY = state.y;
                            state.startCropW = state.width;
                            state.startCropH = state.height;
                            this.captureInput(true);
                            return true;
                        }
                    }
                }

                if (onMouseDown) {
                    return onMouseDown.apply(this, arguments);
                }
            };

            const onMouseMove = nodeType.prototype.onMouseMove;
            nodeType.prototype.onMouseMove = function(e, localPos, graphCanvas) {
                const state = this.cropState;

                if (state.isDragging && state.imageWidth > 0) {
                    const scale = state.previewScale;
                    const dx = (localPos[0] - state.startX) / scale;
                    const dy = (localPos[1] - state.startY) / scale;

                    const snapGrid = this.widgets?.find(w => w.name === "snap_to_grid")?.value || 8;

                    const snap = (val) => Math.round(val / snapGrid) * snapGrid;

                    switch (state.dragMode) {
                        case 'move':
                            state.x = Math.max(0, Math.min(state.imageWidth - state.width, 
                                snap(state.startCropX + dx)));
                            state.y = Math.max(0, Math.min(state.imageHeight - state.height, 
                                snap(state.startCropY + dy)));
                            break;
                        case 'resize-br':
                        case 'new':
                            state.width = Math.max(snapGrid, snap(state.startCropW + dx));
                            state.height = Math.max(snapGrid, snap(state.startCropH + dy));
                            // Clamp to image bounds
                            state.width = Math.min(state.width, state.imageWidth - state.x);
                            state.height = Math.min(state.height, state.imageHeight - state.y);
                            break;
                        case 'resize-tl':
                            const newX = snap(state.startCropX + dx);
                            const newY = snap(state.startCropY + dy);
                            const newW = state.startCropW - (newX - state.startCropX);
                            const newH = state.startCropH - (newY - state.startCropY);
                            if (newW >= snapGrid && newH >= snapGrid && newX >= 0 && newY >= 0) {
                                state.x = newX;
                                state.y = newY;
                                state.width = newW;
                                state.height = newH;
                            }
                            break;
                        case 'resize-tr':
                            const newY2 = snap(state.startCropY + dy);
                            const newW2 = snap(state.startCropW + dx);
                            const newH2 = state.startCropH - (newY2 - state.startCropY);
                            if (newW2 >= snapGrid && newH2 >= snapGrid && newY2 >= 0) {
                                state.y = newY2;
                                state.width = Math.min(newW2, state.imageWidth - state.x);
                                state.height = newH2;
                            }
                            break;
                        case 'resize-bl':
                            const newX2 = snap(state.startCropX + dx);
                            const newW3 = state.startCropW - (newX2 - state.startCropX);
                            const newH3 = snap(state.startCropH + dy);
                            if (newW3 >= snapGrid && newH3 >= snapGrid && newX2 >= 0) {
                                state.x = newX2;
                                state.width = newW3;
                                state.height = Math.min(newH3, state.imageHeight - state.y);
                            }
                            break;
                    }

                    // Update the widget value
                    this.updateCropData();
                    this.setDirtyCanvas(true);
                    return true;
                }

                if (onMouseMove) {
                    return onMouseMove.apply(this, arguments);
                }
            };

            const onMouseUp = nodeType.prototype.onMouseUp;
            nodeType.prototype.onMouseUp = function(e, localPos, graphCanvas) {
                const state = this.cropState;
                if (state.isDragging) {
                    state.isDragging = false;
                    state.dragMode = null;
                    this.captureInput(false);
                    this.updateCropData();
                    this.setDirtyCanvas(true);
                    return true;
                }

                if (onMouseUp) {
                    return onMouseUp.apply(this, arguments);
                }
            };

            // Double-click to reset
            const onDblClick = nodeType.prototype.onDblClick;
            nodeType.prototype.onDblClick = function(e, localPos, graphCanvas) {
                const previewY = this.size[1] - 280;

                if (localPos[1] > previewY + 35) {
                    const state = this.cropState;
                    state.x = 0;
                    state.y = 0;
                    state.width = state.imageWidth || 512;
                    state.height = state.imageHeight || 512;
                    this.updateCropData();
                    this.setDirtyCanvas(true);
                    return true;
                }

                if (onDblClick) {
                    return onDblClick.apply(this, arguments);
                }
            };

            // Update crop_data widget
            nodeType.prototype.updateCropData = function() {
                const state = this.cropState;
                const cropDataWidget = this.widgets?.find(w => w.name === "crop_data");
                if (cropDataWidget) {
                    cropDataWidget.value = JSON.stringify({
                        x: Math.round(state.x),
                        y: Math.round(state.y),
                        width: Math.round(state.width),
                        height: Math.round(state.height)
                    });
                }
            };

            // When image input changes, update dimensions
            const onConnectionsChange = nodeType.prototype.onConnectionsChange;
            nodeType.prototype.onConnectionsChange = function(type, index, connected, link_info) {
                if (onConnectionsChange) {
                    onConnectionsChange.apply(this, arguments);
                }

                // Try to get image dimensions from connected node
                if (type === 1 && index === 0) { // Input connection
                    // We'll set approximate dimensions - actual will come from execution
                    this.cropState.imageWidth = 1024;
                    this.cropState.imageHeight = 1024;
                }
            };

            // Increase node height to accommodate preview
            const onResize = nodeType.prototype.onResize;
            nodeType.prototype.onResize = function(size) {
                size[0] = Math.max(size[0], 300); // Minimum width
                size[1] = Math.max(size[1], 450); // Minimum height for preview
                if (onResize) {
                    return onResize.apply(this, arguments);
                }
            };

            // Set default size when node is added
            const onAdded = nodeType.prototype.onAdded;
            nodeType.prototype.onAdded = function() {
                this.size = [350, 480];
                if (onAdded) {
                    return onAdded.apply(this, arguments);
                }
            };

            // Refresh preview when executed
            const onExecuted = nodeType.prototype.onExecuted;
            nodeType.prototype.onExecuted = function(output) {
                // Force refresh of preview
                this.previewImageSrc = null;
                this.setDirtyCanvas(true);
                if (onExecuted) {
                    return onExecuted.apply(this, arguments);
                }
            };
        }
    },
});

