import { app } from "../../scripts/app.js";

/**
 * VideoPrep Preview Bridge (Advanced) - Mask Editor Extension
 * 
 * KEY PERSISTENCE MECHANISM:
 * The drawn mask is stored as a base64-encoded PNG inside the "mask_data" widget.
 * Since widget values are serialized into the workflow JSON, the mask survives:
 *   - Multiple workflow executions
 *   - ComfyUI restarts
 *   - Saving and loading workflow files
 */

app.registerExtension({
    name: "VideoPrep.PreviewBridgeAdvanced",

    async beforeRegisterNodeDef(nodeType, nodeData, app) {
        if (nodeData.name !== "VideoPrepPreviewBridgeAdvanced") return;

        console.log("[VideoPrep-Bridge Adv] Registering mask editor");

        // ============================================================
        // Node Creation
        // ============================================================
        const onNodeCreated = nodeType.prototype.onNodeCreated;
        nodeType.prototype.onNodeCreated = function() {
            const result = onNodeCreated?.apply(this, arguments);

            this.maskEditor = {
                isDrawing: false,
                brushSize: 30,
                drawMode: "draw",      // "draw" or "erase"
                maskMode: "cut",       // "cut" = paint to remove, "keep" = paint to keep, "extend" = add to existing alpha

                sourceImage: null,
                imageWidth: 0,
                imageHeight: 0,

                maskCanvas: null,      // Stores painted areas (alpha = painted)
                maskCtx: null,

                previewScale: 1,
                previewOffsetX: 0,
                previewOffsetY: 0,

                lastMouseX: 0,
                lastMouseY: 0,
                cursorVisible: false,
                _lastImgSrc: null,
                _lastPaintX: 0,
                _lastPaintY: 0,
                _fetchTimer: null,
                _alphaImported: false,  // Track if we've imported source alpha
            };

            this.size = [400, 550];

            // Start polling for image (handles initial connection)
            this._startImagePoll();

            // Restore mask from widget on creation
            setTimeout(() => this._restoreMaskFromWidget(), 100);

            return result;
        };

        // ============================================================
        // Image polling - fetches preview without needing to run workflow
        // ============================================================
        nodeType.prototype._startImagePoll = function() {
            const me = this.maskEditor;
            if (me._fetchTimer) clearInterval(me._fetchTimer);

            // Poll every 2 seconds for connected image
            me._fetchTimer = setInterval(() => {
                this._fetchSourceImage();
            }, 2000);

            // Also try immediately
            setTimeout(() => this._fetchSourceImage(), 300);
        };

        // ============================================================
        // Restore mask from saved widget value
        // ============================================================
        nodeType.prototype._restoreMaskFromWidget = function() {
            const maskWidget = this.widgets?.find(w => w.name === "mask_data");
            if (maskWidget?.value && maskWidget.value.length > 10) {
                try {
                    const img = new Image();
                    img.onload = () => {
                        const me = this.maskEditor;
                        me.imageWidth = img.width;
                        me.imageHeight = img.height;

                        me.maskCanvas = document.createElement('canvas');
                        me.maskCanvas.width = img.width;
                        me.maskCanvas.height = img.height;
                        me.maskCtx = me.maskCanvas.getContext('2d');

                        // The saved mask is grayscale (white=mask on black bg)
                        // Convert: read R channel, write as alpha on transparent canvas
                        me.maskCtx.clearRect(0, 0, img.width, img.height);

                        const tmpCanvas = document.createElement('canvas');
                        tmpCanvas.width = img.width;
                        tmpCanvas.height = img.height;
                        const tc = tmpCanvas.getContext('2d');
                        tc.drawImage(img, 0, 0);
                        const srcData = tc.getImageData(0, 0, img.width, img.height);

                        const dstData = me.maskCtx.createImageData(img.width, img.height);
                        for (let i = 0; i < srcData.data.length; i += 4) {
                            const val = srcData.data[i]; // R channel = mask value
                            dstData.data[i] = 255;       // R = white
                            dstData.data[i+1] = 255;     // G = white
                            dstData.data[i+2] = 255;     // B = white
                            dstData.data[i+3] = val;     // A = mask value
                        }
                        me.maskCtx.putImageData(dstData, 0, 0);

                        console.log(`[VideoPrep-Bridge Adv] Restored mask: ${img.width}x${img.height}`);
                        this.setDirtyCanvas(true);
                    };
                    img.src = "data:image/png;base64," + maskWidget.value;
                } catch (e) {
                    console.error("[VideoPrep-Bridge Adv] Failed to restore mask:", e);
                }
            }
        };

        // ============================================================
        // onConfigure - Restore on workflow load
        // ============================================================
        const onConfigure = nodeType.prototype.onConfigure;
        nodeType.prototype.onConfigure = function(info) {
            if (onConfigure) onConfigure.apply(this, arguments);
            setTimeout(() => {
                this._restoreMaskFromWidget();
                this._startImagePoll();
            }, 200);
        };

        // ============================================================
        // Save mask to widget (base64 PNG)
        // ============================================================
        nodeType.prototype._saveMaskToWidget = function() {
            const me = this.maskEditor;
            if (!me.maskCanvas) return;

            const maskWidget = this.widgets?.find(w => w.name === "mask_data");
            if (!maskWidget) return;

            const data = me.maskCtx.getImageData(0, 0, me.maskCanvas.width, me.maskCanvas.height);
            let hasContent = false;
            for (let i = 3; i < data.data.length; i += 4) {
                if (data.data[i] > 10) { hasContent = true; break; }
            }

            if (hasContent) {
                // Export as grayscale: white = area to KEEP
                // Cut mode: painted = remove → invert
                // Keep/Extend mode: painted = keep → direct
                const invert = (me.maskMode === "cut");

                const exportCanvas = document.createElement('canvas');
                exportCanvas.width = me.maskCanvas.width;
                exportCanvas.height = me.maskCanvas.height;
                const ec = exportCanvas.getContext('2d');

                const exportData = ec.createImageData(exportCanvas.width, exportCanvas.height);
                for (let i = 0; i < data.data.length; i += 4) {
                    const alpha = data.data[i + 3];  // Painted intensity
                    const maskVal = invert ? (255 - alpha) : alpha;  // Invert if needed
                    exportData.data[i] = maskVal;     // R
                    exportData.data[i+1] = maskVal;   // G
                    exportData.data[i+2] = maskVal;   // B
                    exportData.data[i+3] = 255;       // A = fully opaque
                }
                ec.putImageData(exportData, 0, 0);

                const dataUrl = exportCanvas.toDataURL('image/png');
                maskWidget.value = dataUrl.replace('data:image/png;base64,', '');
            } else {
                maskWidget.value = "";
            }
        };

        // ============================================================
        // Initialize mask canvas for current image
        // ============================================================
        nodeType.prototype._ensureMaskCanvas = function(imgWidth, imgHeight) {
            const me = this.maskEditor;

            if (me.maskCanvas && me.maskCanvas.width === imgWidth && me.maskCanvas.height === imgHeight) {
                return;
            }

            const oldCanvas = me.maskCanvas;

            me.maskCanvas = document.createElement('canvas');
            me.maskCanvas.width = imgWidth;
            me.maskCanvas.height = imgHeight;
            me.maskCtx = me.maskCanvas.getContext('2d');
            // Start TRANSPARENT (all zeros) - NOT black!
            // Black fill has alpha=255 which means "everything masked"
            me.maskCtx.clearRect(0, 0, imgWidth, imgHeight);

            if (oldCanvas && oldCanvas.width > 0) {
                me.maskCtx.drawImage(oldCanvas, 0, 0, imgWidth, imgHeight);
            }

            me.imageWidth = imgWidth;
            me.imageHeight = imgHeight;
        };

        // ============================================================
        // Fetch source image from connected node (works before execution)
        // ============================================================
        nodeType.prototype._fetchSourceImage = function() {
            const me = this.maskEditor;
            if (!me) return;

            const input = this.inputs?.[0];  // "image" input
            if (!input?.link) { me.sourceImage = null; me._lastImgSrc = null; return; }

            const link = app.graph.links[input.link];
            if (!link) return;

            const sourceNode = app.graph.getNodeById(link.origin_id);
            if (!sourceNode) return;

            let imgSrc = null;

            // Method 1: node.imgs (after execution)
            if (sourceNode.imgs?.length > 0) {
                const img = sourceNode.imgs[0];
                if (img?.src) imgSrc = img.src;
                else if (img?.currentSrc) imgSrc = img.currentSrc;
            }

            // Method 2: LoadImage widget (works before execution!)
            if (!imgSrc && (sourceNode.type === "LoadImage" || sourceNode.comfyClass === "LoadImage")) {
                const w = sourceNode.widgets?.find(w => w.name === "image");
                if (w?.value) {
                    imgSrc = `${window.location.origin}/view?filename=${encodeURIComponent(w.value)}&type=input`;
                }
            }

            // Method 3: Any preview bridge / preview node
            if (!imgSrc && sourceNode.imageIndex !== undefined && sourceNode.images) {
                const img = sourceNode.images[sourceNode.imageIndex];
                if (img?.src) imgSrc = img.src;
            }

            // Method 4: widgets_values with image filenames
            if (!imgSrc && sourceNode.widgets_values) {
                for (const val of sourceNode.widgets_values) {
                    if (typeof val === "string" && (val.endsWith(".png") || val.endsWith(".jpg") || val.endsWith(".webp"))) {
                        imgSrc = `${window.location.origin}/view?filename=${encodeURIComponent(val)}&type=input`;
                        break;
                    }
                }
            }

            // Method 5: Recursively follow upstream node chain
            if (!imgSrc && sourceNode.inputs) {
                for (const inp of sourceNode.inputs) {
                    if (inp.link && inp.type === "IMAGE") {
                        const upLink = app.graph.links[inp.link];
                        if (upLink) {
                            const upNode = app.graph.getNodeById(upLink.origin_id);
                            if (upNode?.imgs?.length > 0 && upNode.imgs[0]?.src) {
                                imgSrc = upNode.imgs[0].src;
                                break;
                            }
                        }
                    }
                }
            }

            if (!imgSrc) return;
            if (me._lastImgSrc === imgSrc && me.sourceImage?.complete) return;
            me._lastImgSrc = imgSrc;

            const img = new Image();
            img.crossOrigin = "anonymous";
            img.onload = () => {
                me.sourceImage = img;
                this._ensureMaskCanvas(img.naturalWidth, img.naturalHeight);

                // Auto-import alpha if the source image has transparency
                // In Extend mode, always try to import; in other modes only if no mask drawn yet
                if (!me._alphaImported && (me.maskMode === "extend" || !this._hasMaskContent())) {
                    this._importAlphaFromImage(img);
                }

                this.setDirtyCanvas(true);
            };
            img.onerror = () => {
                console.log("[VideoPrep-Bridge Adv] Image load failed, will retry");
            };
            img.src = imgSrc;
        };

        // ============================================================
        // Coordinate conversion
        // ============================================================
        nodeType.prototype._screenToImage = function(sx, sy) {
            const me = this.maskEditor;
            return {
                x: (sx - me.previewOffsetX) / me.previewScale,
                y: (sy - me.previewOffsetY) / me.previewScale,
            };
        };

        // ============================================================
        // Import alpha channel from source image into mask canvas
        // ============================================================
        nodeType.prototype._importAlphaFromImage = function(img) {
            const me = this.maskEditor;
            if (!me.maskCanvas || !img?.complete) return;

            try {
                // Read the source image to check for alpha
                const tmp = document.createElement('canvas');
                tmp.width = img.naturalWidth;
                tmp.height = img.naturalHeight;
                const tc = tmp.getContext('2d');
                tc.drawImage(img, 0, 0);
                const data = tc.getImageData(0, 0, tmp.width, tmp.height);

                // Check if image has meaningful alpha (not all 255)
                let hasAlpha = false;
                let alphaMin = 255;
                for (let i = 3; i < data.data.length; i += 4) {
                    if (data.data[i] < alphaMin) alphaMin = data.data[i];
                    if (data.data[i] < 250) { hasAlpha = true; }
                    if (hasAlpha && alphaMin < 200) break;  // Quick exit
                }

                if (hasAlpha) {
                    // Import alpha into our mask canvas
                    const maskData = me.maskCtx.createImageData(tmp.width, tmp.height);

                    if (me.maskMode === "cut") {
                        // CUT mode: transparent pixels → painted (to be removed)
                        for (let i = 0; i < data.data.length; i += 4) {
                            const alpha = data.data[i + 3];
                            maskData.data[i] = 255;
                            maskData.data[i+1] = 255;
                            maskData.data[i+2] = 255;
                            maskData.data[i+3] = 255 - alpha;  // Invert: transparent = painted
                        }
                    } else {
                        // KEEP/EXTEND mode: opaque pixels → painted (to be kept)
                        for (let i = 0; i < data.data.length; i += 4) {
                            const alpha = data.data[i + 3];
                            maskData.data[i] = 255;
                            maskData.data[i+1] = 255;
                            maskData.data[i+2] = 255;
                            maskData.data[i+3] = alpha;  // Direct: opaque = painted
                        }
                    }

                    me.maskCtx.putImageData(maskData, 0, 0);
                    me._alphaImported = true;

                    this._saveMaskToWidget();
                    console.log(`[VideoPrep-Bridge Adv] Imported alpha (${me.maskMode} mode, min alpha: ${alphaMin})`);
                }
            } catch (e) {
                // CORS or other error - that's fine, just skip
                console.log("[VideoPrep-Bridge Adv] Could not read source alpha:", e.message);
            }
        };

        // ============================================================
        // Paint on mask
        // ============================================================
        nodeType.prototype._paintOnMask = function(imgX, imgY, erase) {
            const me = this.maskEditor;
            if (!me.maskCtx) return;

            me.maskCtx.globalCompositeOperation = erase ? 'destination-out' : 'source-over';
            me.maskCtx.fillStyle = '#ffffff';
            me.maskCtx.beginPath();
            me.maskCtx.arc(imgX, imgY, me.brushSize / 2, 0, Math.PI * 2);
            me.maskCtx.fill();
            me.maskCtx.globalCompositeOperation = 'source-over';
        };

        nodeType.prototype._paintLine = function(x1, y1, x2, y2, erase) {
            const me = this.maskEditor;
            const dist = Math.sqrt((x2-x1)**2 + (y2-y1)**2);
            const steps = Math.max(1, Math.ceil(dist / (me.brushSize / 4)));

            for (let i = 0; i <= steps; i++) {
                const t = i / steps;
                this._paintOnMask(x1 + (x2-x1)*t, y1 + (y2-y1)*t, erase);
            }
        };

        // ============================================================
        // Check if mask has any painted content
        // ============================================================
        nodeType.prototype._hasMaskContent = function() {
            const me = this.maskEditor;
            if (!me.maskCanvas || !me.maskCtx) return false;
            const data = me.maskCtx.getImageData(0, 0, me.maskCanvas.width, me.maskCanvas.height);
            // Check ALPHA channel (index 3) since canvas is transparent
            for (let i = 3; i < data.data.length; i += 4) {
                if (data.data[i] > 10) return true;
            }
            return false;
        };

        // ============================================================
        // Suppress default ComfyUI image preview (it overlaps our editor)
        // ============================================================
        const onExecuted = nodeType.prototype.onExecuted;
        nodeType.prototype.onExecuted = function(output) {
            // Do NOT call the default onExecuted which sets this.imgs
            // That would overlay ComfyUI's built-in image preview on top of our editor
            // Instead, just update our source image if needed
            if (output?.images?.length > 0) {
                // Refresh source image after execution
                const me = this.maskEditor;
                if (me) {
                    me._lastImgSrc = null;  // Force re-fetch
                    setTimeout(() => this._fetchSourceImage(), 200);
                }
            }
            // Don't call super - prevents default preview
        };

        // Also prevent any imgs from being set externally
        const onDrawBackground = nodeType.prototype.onDrawBackground;
        nodeType.prototype.onDrawBackground = function(ctx) {
            // Clear any imgs that might have been set (prevents built-in preview)
            if (this.imgs) this.imgs = null;
            if (onDrawBackground) return onDrawBackground.apply(this, arguments);
        };

        // ============================================================
        // Draw Foreground
        // ============================================================
        const onDrawForeground = nodeType.prototype.onDrawForeground;
        nodeType.prototype.onDrawForeground = function(ctx) {
            try {
                if (onDrawForeground) onDrawForeground.apply(this, arguments);

                const me = this.maskEditor;
                if (!me) return;

                // Don't draw editor when node is collapsed
                if (this.flags?.collapsed) return;

                // Clear any imgs that may have been set by ComfyUI
                if (this.imgs) this.imgs = null;

                // Visually hide mask_data widget WITHOUT changing its type
                // CRITICAL: Setting type to "converted-widget" stops ComfyUI 
                // from sending the value to Python! We must keep the original type.
                if (this.widgets && !this._widgetsHidden) {
                    this._widgetsHidden = true;
                    for (const w of this.widgets) {
                        if (w.name === "mask_data") {
                            // Make it visually invisible but still functional
                            w.computeSize = () => [0, -4];
                            if (w.inputEl) {
                                w.inputEl.style.display = "none";
                            }
                        }
                    }
                }

                // === LAYOUT ===
                const M = 8;  // margin
                const nodeW = this.size[0];
                const nodeH = this.size[1];
                const contentW = nodeW - M * 2;

                // Compute start Y below all inputs + visible widgets
                const inputCount = this.inputs ? this.inputs.length : 0;
                const visibleWidgets = this.widgets ? this.widgets.filter(
                    w => !w.hidden && w.type !== "converted-widget"
                ).length : 0;
                const startY = 26 + inputCount * 20 + visibleWidgets * 26;

                // Fixed layout regions (from top to bottom)
                const TOOLBAR_H = 30;
                const STATUS_H = 18;
                const GAP = 4;

                const toolbarY = startY;
                const previewY = toolbarY + TOOLBAR_H + GAP;
                const statusY  = nodeH - STATUS_H - M;
                const previewH = Math.max(80, statusY - previewY - GAP);

                // === TOOLBAR ===
                ctx.fillStyle = "#2a2a3e";
                ctx.beginPath();
                ctx.roundRect(M, toolbarY, contentW, TOOLBAR_H, 4);
                ctx.fill();

                // Buttons: Mode toggle, Draw, Erase, Clear + slider
                const btnW = Math.floor(contentW / 6);

                // Mode button colors/labels
                const modeConfig = {
                    cut:    { label: "✂ Cut",    color: "#e74c3c" },
                    keep:   { label: "✚ Keep",   color: "#27ae60" },
                    extend: { label: "↔ Extend", color: "#3498db" },
                };
                const mc = modeConfig[me.maskMode] || modeConfig.cut;

                const btns = [
                    { label: mc.label, mode: "toggle_mode", color: mc.color },
                    { label: "🖌 Draw", mode: "draw" },
                    { label: "🧹 Erase", mode: "erase" },
                    { label: "🗑", mode: "clear" },
                ];

                ctx.font = "bold 10px Arial";
                ctx.textAlign = "center";

                btns.forEach((btn, i) => {
                    const bx = M + 3 + i * (btnW + 1);
                    let bgColor;

                    if (btn.mode === "toggle_mode") {
                        bgColor = btn.color;
                    } else {
                        const active = (btn.mode === me.drawMode && btn.mode !== "clear");
                        bgColor = active ? "#4ecdc4" : "#444";
                    }

                    ctx.fillStyle = bgColor;
                    ctx.beginPath();
                    ctx.roundRect(bx, toolbarY + 4, btnW - 2, TOOLBAR_H - 8, 3);
                    ctx.fill();

                    ctx.fillStyle = "#fff";
                    ctx.fillText(btn.label, bx + (btnW - 2) / 2, toolbarY + 20);
                });

                // Brush size slider area (after 4 buttons)
                const bsX = M + 3 + 4 * (btnW + 1);
                const bsW = contentW - (bsX - M) - 3;

                // Background
                ctx.fillStyle = "#333";
                ctx.beginPath();
                ctx.roundRect(bsX, toolbarY + 4, bsW, TOOLBAR_H - 8, 3);
                ctx.fill();

                // Slider track
                const trackX = bsX + 8;
                const trackW = bsW - 16;
                const trackY = toolbarY + 18;

                ctx.fillStyle = "#222";
                ctx.beginPath();
                ctx.roundRect(trackX, trackY, trackW, 6, 3);
                ctx.fill();

                // Slider fill (brush 2-200 mapped to 0-1)
                const sliderT = (me.brushSize - 2) / 198;
                const fillW = sliderT * trackW;
                const sliderColor = me.drawMode === "erase" ? "#ff6b6b" : "#4ecdc4";

                ctx.fillStyle = sliderColor;
                ctx.beginPath();
                ctx.roundRect(trackX, trackY, fillW, 6, 3);
                ctx.fill();

                // Slider handle
                const handleX = trackX + fillW;
                ctx.fillStyle = "#fff";
                ctx.beginPath();
                ctx.arc(handleX, trackY + 3, 5, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = sliderColor;
                ctx.lineWidth = 1.5;
                ctx.stroke();

                // Label
                ctx.fillStyle = "#ccc";
                ctx.font = "bold 10px Arial";
                ctx.textAlign = "center";
                ctx.fillText(`${me.brushSize}px`, bsX + bsW / 2, toolbarY + 13);

                // Store slider bounds for drag detection
                me._sliderBounds = { x: trackX, y: trackY - 4, w: trackW, h: 14, areaX: bsX, areaW: bsW };

                // Store toolbar bounds for click detection
                me._toolbarY = toolbarY;
                me._toolbarH = TOOLBAR_H;
                me._btnW = btnW;

                // === PREVIEW AREA ===
                // Clip everything to the preview rectangle
                ctx.save();
                ctx.beginPath();
                ctx.rect(M, previewY, contentW, previewH);
                ctx.clip();

                // Preview background
                ctx.fillStyle = "#111118";
                ctx.fillRect(M, previewY, contentW, previewH);

                if (me.sourceImage?.complete && me.sourceImage.naturalWidth > 0) {
                    // Scale to fit preview area
                    const scale = Math.min(
                        (contentW - 4) / me.sourceImage.naturalWidth,
                        (previewH - 4) / me.sourceImage.naturalHeight
                    );
                    me.previewScale = scale;

                    const scaledW = me.sourceImage.naturalWidth * scale;
                    const scaledH = me.sourceImage.naturalHeight * scale;
                    const imgX = M + (contentW - scaledW) / 2;
                    const imgY = previewY + (previewH - scaledH) / 2;

                    me.previewOffsetX = imgX;
                    me.previewOffsetY = imgY;

                    // Checkerboard (transparency indicator)
                    const cs = 8;
                    for (let cy = 0; cy < scaledH; cy += cs) {
                        for (let cx = 0; cx < scaledW; cx += cs) {
                            ctx.fillStyle = ((Math.floor(cx/cs) + Math.floor(cy/cs)) % 2 === 0) ? "#303030" : "#404040";
                            ctx.fillRect(imgX + cx, imgY + cy, Math.min(cs, scaledW - cx), Math.min(cs, scaledH - cy));
                        }
                    }

                    // Draw source image
                    ctx.drawImage(me.sourceImage, imgX, imgY, scaledW, scaledH);

                    // Draw mask overlay if we have mask content
                    if (me.maskCanvas && me.maskCanvas.width > 0 && this._hasMaskContent()) {
                        const sw = Math.ceil(scaledW);
                        const sh = Math.ceil(scaledH);

                        if (me.maskMode === "cut") {
                            // CUT: Painted = will be removed → red tint on painted areas
                            ctx.save();
                            const overlay = document.createElement('canvas');
                            overlay.width = sw;
                            overlay.height = sh;
                            const oc = overlay.getContext('2d');
                            oc.fillStyle = 'rgba(200, 40, 40, 0.5)';
                            oc.fillRect(0, 0, sw, sh);
                            oc.globalCompositeOperation = 'destination-in';
                            oc.drawImage(me.maskCanvas, 0, 0, sw, sh);
                            ctx.drawImage(overlay, imgX, imgY);
                            ctx.restore();

                        } else {
                            // KEEP & EXTEND: Painted = will be kept → darken unpainted, bright on painted
                            ctx.fillStyle = "rgba(0, 0, 0, 0.55)";
                            ctx.fillRect(imgX, imgY, scaledW, scaledH);

                            const tmp = document.createElement('canvas');
                            tmp.width = sw;
                            tmp.height = sh;
                            const tc = tmp.getContext('2d');
                            tc.drawImage(me.sourceImage, 0, 0, sw, sh);
                            tc.globalCompositeOperation = 'destination-in';
                            tc.drawImage(me.maskCanvas, 0, 0, sw, sh);
                            ctx.drawImage(tmp, imgX, imgY);

                            // Tint color: green for Keep, blue for Extend
                            const tintColor = me.maskMode === "extend" ? '#3498db' : '#4ecdc4';
                            ctx.save();
                            ctx.globalAlpha = 0.12;
                            const tint = document.createElement('canvas');
                            tint.width = sw;
                            tint.height = sh;
                            const tc2 = tint.getContext('2d');
                            tc2.fillStyle = tintColor;
                            tc2.fillRect(0, 0, sw, sh);
                            tc2.globalCompositeOperation = 'destination-in';
                            tc2.drawImage(me.maskCanvas, 0, 0, sw, sh);
                            ctx.drawImage(tint, imgX, imgY);
                            ctx.restore();
                        }
                    }

                    // Draw brush cursor
                    if (me.cursorVisible) {
                        const brushR = (me.brushSize / 2) * me.previewScale;
                        ctx.strokeStyle = me.drawMode === "erase" ? "#ff6b6b" : "#4ecdc4";
                        ctx.lineWidth = 1.5;
                        ctx.setLineDash([4, 4]);
                        ctx.beginPath();
                        ctx.arc(me.lastMouseX, me.lastMouseY, brushR, 0, Math.PI * 2);
                        ctx.stroke();
                        ctx.setLineDash([]);

                        ctx.fillStyle = me.drawMode === "erase" ? "#ff6b6b" : "#4ecdc4";
                        ctx.beginPath();
                        ctx.arc(me.lastMouseX, me.lastMouseY, 2, 0, Math.PI * 2);
                        ctx.fill();
                    }

                } else {
                    ctx.fillStyle = "#555";
                    ctx.font = "13px Arial";
                    ctx.textAlign = "center";
                    ctx.fillText("Connect an image input", M + contentW / 2, previewY + previewH / 2 - 8);
                    ctx.font = "11px Arial";
                    ctx.fillStyle = "#444";
                    ctx.fillText("Preview appears automatically", M + contentW / 2, previewY + previewH / 2 + 12);
                }

                ctx.restore();  // Remove clip

                // Preview border
                ctx.strokeStyle = "#333";
                ctx.lineWidth = 1;
                ctx.strokeRect(M, previewY, contentW, previewH);

                // Store preview bounds for hit testing
                me._previewBounds = { x: M, y: previewY, w: contentW, h: previewH };

                // === STATUS BAR ===
                ctx.font = "10px Arial";

                if (me.sourceImage?.complete) {
                    const hasMask = this._hasMaskContent();
                    const modeHints = { cut: "remove", keep: "select", extend: "extend" };

                    ctx.fillStyle = hasMask ? "#4ecdc4" : "#666";
                    ctx.textAlign = "left";
                    ctx.fillText(
                        hasMask ? `✓ Mask saved (${me.maskMode} mode)` : `Paint to ${modeHints[me.maskMode]} areas`,
                        M + 4, statusY + 12
                    );

                    ctx.fillStyle = "#555";
                    ctx.textAlign = "right";
                    ctx.fillText(
                        `${me.sourceImage.naturalWidth}×${me.sourceImage.naturalHeight}`,
                        M + contentW - 4, statusY + 12
                    );
                }

            } catch (e) {
                console.error("[VideoPrep-Bridge Adv] Draw error:", e);
            }
        };

        // ============================================================
        // Mouse Down
        // ============================================================
        const onMouseDown = nodeType.prototype.onMouseDown;
        nodeType.prototype.onMouseDown = function(e, localPos, graphCanvas) {
            const me = this.maskEditor;
            if (!me) return onMouseDown?.apply(this, arguments);

            // Toolbar area
            if (localPos[1] >= me._toolbarY && localPos[1] < me._toolbarY + me._toolbarH) {

                // Check brush slider first
                const sl = me._sliderBounds;
                if (sl && localPos[0] >= sl.areaX && localPos[0] < sl.areaX + sl.areaW) {
                    me._draggingSlider = true;
                    const t = Math.max(0, Math.min(1, (localPos[0] - sl.x) / sl.w));
                    me.brushSize = Math.round(2 + t * 198);
                    this.setDirtyCanvas(true);
                    return true;
                }

                // Buttons: 0=Toggle, 1=Draw, 2=Erase, 3=Clear
                const idx = Math.floor((localPos[0] - 8 - 3) / (me._btnW + 1));

                if (idx === 0) {
                    // Cycle: Cut → Keep → Extend → Cut...
                    const modes = ["cut", "keep", "extend"];
                    const currentIdx = modes.indexOf(me.maskMode);
                    const oldMode = me.maskMode;
                    me.maskMode = modes[(currentIdx + 1) % 3];

                    // When switching to Extend, auto-import source alpha if not already done
                    if (me.maskMode === "extend" && me.sourceImage?.complete && !this._hasMaskContent()) {
                        me._alphaImported = false;
                        this._importAlphaFromImage(me.sourceImage);
                    }

                    this._saveMaskToWidget();  // Re-export with new mode
                    this.setDirtyCanvas(true);
                    return true;
                }
                if (idx === 1) { me.drawMode = "draw"; this.setDirtyCanvas(true); return true; }
                if (idx === 2) { me.drawMode = "erase"; this.setDirtyCanvas(true); return true; }
                if (idx === 3 && me.maskCtx) {
                    me.maskCtx.clearRect(0, 0, me.maskCanvas.width, me.maskCanvas.height);
                    me._alphaImported = false;
                    this._saveMaskToWidget();
                    this.setDirtyCanvas(true);
                    return true;
                }
                return true;
            }

            // Preview area - drawing
            const pb = me._previewBounds;
            if (pb && me.sourceImage?.complete && me.maskCanvas &&
                localPos[0] >= pb.x && localPos[0] < pb.x + pb.w &&
                localPos[1] >= pb.y && localPos[1] < pb.y + pb.h) {

                const ic = this._screenToImage(localPos[0], localPos[1]);

                if (ic.x >= 0 && ic.x < me.imageWidth && ic.y >= 0 && ic.y < me.imageHeight) {
                    const erase = (e.button === 2) || me.drawMode === "erase";

                    me.isDrawing = true;
                    me._lastPaintX = ic.x;
                    me._lastPaintY = ic.y;

                    this._paintOnMask(ic.x, ic.y, erase);
                    this.setDirtyCanvas(true);

                    e.preventDefault?.();
                    e.stopPropagation?.();
                    return true;
                }
            }

            return onMouseDown?.apply(this, arguments);
        };

        // ============================================================
        // Mouse Move
        // ============================================================
        const onMouseMove = nodeType.prototype.onMouseMove;
        nodeType.prototype.onMouseMove = function(e, localPos, graphCanvas) {
            const me = this.maskEditor;
            if (!me) return onMouseMove?.apply(this, arguments);

            const pb = me._previewBounds;
            if (pb && localPos[0] >= pb.x && localPos[0] < pb.x + pb.w &&
                localPos[1] >= pb.y && localPos[1] < pb.y + pb.h) {
                me.cursorVisible = true;
                me.lastMouseX = localPos[0];
                me.lastMouseY = localPos[1];
            } else {
                me.cursorVisible = false;
            }

            // Slider dragging
            if (me._draggingSlider) {
                if (e.buttons === 0) {
                    me._draggingSlider = false;
                    this.setDirtyCanvas(true);
                    return true;
                }
                const sl = me._sliderBounds;
                if (sl) {
                    const t = Math.max(0, Math.min(1, (localPos[0] - sl.x) / sl.w));
                    me.brushSize = Math.round(2 + t * 198);
                    this.setDirtyCanvas(true);
                }
                return true;
            }

            if (me.isDrawing && me.maskCanvas) {
                if (e.buttons === 0) {
                    me.isDrawing = false;
                    this._saveMaskToWidget();
                    this.setDirtyCanvas(true);
                    return true;
                }

                const ic = this._screenToImage(localPos[0], localPos[1]);
                const erase = (e.buttons === 2) || me.drawMode === "erase";

                this._paintLine(me._lastPaintX, me._lastPaintY, ic.x, ic.y, erase);
                me._lastPaintX = ic.x;
                me._lastPaintY = ic.y;

                this.setDirtyCanvas(true);
                return true;
            }

            this.setDirtyCanvas(true);
            return onMouseMove?.apply(this, arguments);
        };

        // ============================================================
        // Mouse Up
        // ============================================================
        const onMouseUp = nodeType.prototype.onMouseUp;
        nodeType.prototype.onMouseUp = function(e, localPos, graphCanvas) {
            const me = this.maskEditor;
            if (me?._draggingSlider) {
                me._draggingSlider = false;
                this.setDirtyCanvas(true);
                return true;
            }
            if (me?.isDrawing) {
                me.isDrawing = false;
                this._saveMaskToWidget();
                this.setDirtyCanvas(true);
                return true;
            }
            return onMouseUp?.apply(this, arguments);
        };

        // ============================================================
        // Mouse Leave
        // ============================================================
        const onMouseLeave = nodeType.prototype.onMouseLeave;
        nodeType.prototype.onMouseLeave = function(e) {
            const me = this.maskEditor;
            if (me) {
                me.cursorVisible = false;
                me._draggingSlider = false;
                if (me.isDrawing) {
                    me.isDrawing = false;
                    this._saveMaskToWidget();
                }
                this.setDirtyCanvas(true);
            }
            return onMouseLeave?.apply(this, arguments);
        };

        // Mouse wheel removed - using slider instead (ComfyUI captures scroll)

        // ============================================================
        // Connection changes - auto-fetch image
        // ============================================================
        const onConnectionsChange = nodeType.prototype.onConnectionsChange;
        nodeType.prototype.onConnectionsChange = function(type, index, connected, linkInfo) {
            const me = this.maskEditor;
            if (me) {
                if (type === 1 && index === 0) {
                    if (!connected) {
                        me.sourceImage = null;
                        me._lastImgSrc = null;
                    } else {
                        // New connection - try to fetch immediately
                        setTimeout(() => this._fetchSourceImage(), 100);
                    }
                    this.setDirtyCanvas(true);
                }
            }
            return onConnectionsChange?.apply(this, arguments);
        };

        // ============================================================
        // Clean up on removal
        // ============================================================
        const onRemoved = nodeType.prototype.onRemoved;
        nodeType.prototype.onRemoved = function() {
            const me = this.maskEditor;
            if (me?._fetchTimer) clearInterval(me._fetchTimer);
            return onRemoved?.apply(this, arguments);
        };
    }
});
